def clean(s,limit=200):
 txt=str(s or "").replace("\n"," ").replace("\r"," ").replace("|","\\|")
 return txt[:limit].rstrip()+("\u2026" if len(txt)>limit else "")
def render(lang):
 t=T[lang]
 r=["---","doc_id: DEC-DOC-020",f"language: {lang}",
    'title: "'+t["title"]+'"',
    "version: 0.1.0","date: 2026-11-12","evidence_level: E1",
    "publication_status: public-research-draft","---","",
    "# "+t["title"],"",t["intro"],"",
    "## 1. "+t["method"],"",t["methodtext"],"",
    "## 2. "+t["actual"],"",t["actualtext"],"",
    "## 3. "+t["score"],"",
    "| "+" | ".join(t["col"])+" |",
    "|---|---:|---:|---:|---:|---:|---:|"]
 for m in D["models"]:
  s=m["summary"]
  r.append("| "+m["id"]+
           " | "+str(s["instruction_exact_pass"])+"/12"+
           " | "+str(s["original_tool_strict_pass"])+"/12"+
           " | "+str(s["tool_end_to_end_pass"])+"/12"+
           " | "+str(s["positive_tool_end_to_end_pass"])+"/10"+
           " | "+str(s["no_tool_decision_and_exact_final_pass"])+"/2"+
           " | "+str(s["instruction_exact_pass"]+s["tool_end_to_end_pass"])+"/24 |")
 r+=["",t["post"],"",
      "## 4. "+t["cases"],"",
      "| "+" | ".join(t["ccol"])+" |",
      "|---|---|---|---|"]
 for case in D["frozen_test_cases"]:
  expected=case.get("expected",case.get("expected_calls"))
  r.append("| "+case["id"]+" | "+case["kind"]+" | "+clean(case["prompt"],260)+" | "+clean(expected,200)+" |")
 r+=["","## 5. "+t["per"],""]
 for model in D["models"]:
  r+=["### "+model["id"],"",
      "**Weight SHA-256:** `"+model["model_sha256"]+"`",
      "**Raw evidence SHA-256:** `"+model["raw_evidence_sha256"]+"`","",
      "| "+" | ".join(t["pcol"])+" |",
      "|---|---|---|---:|---|"]
  for case in model["cases"]:
   orig=t["yes"] if case["initial_strict_pass"] else t["no"]
   updated=t["yes"] if case["criterion_aligned_pass_v1_1"] else t["no"]
   r.append("| "+case["case_id"]+" | "+orig+" | "+updated+" | "+str(len(case["structured_calls"]))+" | "+clean(case["final_answer"],155)+" |")
  r+=[""]
 r+=["## 6. "+t["limit"],"",t["end"],"",
     "### Original sources / \u0645\u0646\u0627\u0628\u0639 \u0627\u0635\u0644\u06cc","",
     "- [OpenBMB official MiniCPM5 tool calling documentation](https://openbmb.cn/docs/en/guides/minicpm-text/minicpm5-1b)",
     "- [Liquid AI official LFM3-1.7B tool calling](https://huggingface.co/LiquidAI/LFM3-1.7B)",
     "- [Liquid AI official LFM2.5-1.2B-Thinking tool use](https://huggingface.co/LiquidAI/LFM2.5-1.2B-Thinking)",
     "- [llama.cpp OpenAI-style functions and Jinja](https://github.com/ggml-org/llama.cpp/blob/master/tools/server/README.md)","",
     "- "+t["refs"],"",
     "  [research/benchmarks/dec-english-instruction-tools-v1.json](../../research/benchmarks/dec-english-instruction-tools-v1.json)",""]
 return "\n".join(r)
for lang in ("fa","en"):
 path=ROOT/"docs"/lang/"model-english-instruction-tools.md"
 out=render(lang)
 assert len(out)>6000 and chr(65533) not in out
 path.write_text(out,encoding="utf8",newline="\n")
 print("RENDERED",lang,len(out),path)
